// ===== TRADING COMPS GUIDES (content only, no logic) =====
// Every input and major calculation has a ten-part guide: what it is, why it matters, how to find the data,
// how to calculate it, a worked example, how to read the result, how to choose, common mistakes, sources,
// and the analyst's own research notes (stored in the model). Worked examples say whether their figures
// are taken from a filing (with the filing named) or are illustrative arithmetic.
const CompsHelp = (() => {
  // [title, url, kind] kind: 'direct' (the data page itself), 'method' (explains the method), 'raw' (a search or filing index)
  const S = {
    edgarFts: ['SEC EDGAR full-text search (search the 10-K and 10-Q text)', 'https://www.sec.gov/edgar/search/', 'raw'],
    secApi: ['SEC: EDGAR application programming interfaces (company facts and submissions files)', 'https://www.sec.gov/search-filings/edgar-application-programming-interfaces', 'method'],
    secNonGaap: ['SEC staff interpretations: Non-GAAP financial measures (adjusted EBITDA and "non-recurring" labels)', 'https://www.sec.gov/rules-regulations/staff-guidance/corporation-finance-interpretations/non-gaap-financial-measures', 'method'],
    cfaMult: ['CFA Institute refresher reading: Market-Based Valuation: Price and Enterprise Value Multiples', 'https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/market-based-valuation-price-enterprise-value-multiples', 'method'],
    damCh17: ['Damodaran, Investment Valuation, chapter 17: fundamental principles of relative valuation (PDF)', 'https://pages.stern.nyu.edu/~adamodar/pdfiles/valn2ed/ch17.pdf', 'method'],
    damCh18: ['Damodaran, Investment Valuation, chapter 18: earnings multiples (PDF)', 'https://pages.stern.nyu.edu/~adamodar/pdfiles/valn2ed/ch18.pdf', 'method'],
    damCh20: ['Damodaran, Investment Valuation, chapter 20: revenue and sector-specific multiples (PDF)', 'https://pages.stern.nyu.edu/~adamodar/pdfiles/valn2ed/ch20.pdf', 'method'],
    damEbitda: ['Damodaran: EV/EBITDA, EV/EBIT and other value multiples by industry (US, updated each January)', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/vebitda.html', 'direct'],
    damPE: ['Damodaran: price-earnings ratios by industry', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/pedata.html', 'direct'],
    damPS: ['Damodaran: price-to-sales and EV/sales ratios by industry', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/psdata.html', 'direct'],
    damPBV: ['Damodaran: price-to-book ratios by industry', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/datafile/pbvdata.html', 'direct'],
    ifrs16: ['IFRS Foundation: IFRS 16 Leases (all lease costs leave EBITDA under IFRS)', 'https://www.ifrs.org/issued-standards/list-of-standards/ifrs-16-leases/', 'method'],
    fedH10: ['Federal Reserve H.10: foreign exchange rates (weekly, noon buying rates in New York)', 'https://www.federalreserve.gov/releases/h10/current/', 'direct'],
    msPct: ['Microsoft: PERCENTILE.INC function (the quartile convention used here)', 'https://support.microsoft.com/en-us/excel/functions/percentile-inc-function', 'method'],
    fmp: ['Financial Modeling Prep API documentation (quotes, statements, analyst estimates, peers)', 'https://site.financialmodelingprep.com/developer/docs', 'method'],
    yahoo: ['Yahoo Finance quote page (price, market cap; check the quote time)', 'https://finance.yahoo.com/', 'direct'],
  };
  const ILL = 'Illustrative arithmetic, not company data.';
  const AMZN_TTM = 'Amazon (from its filings): FY2025 revenue 716,924 $mm (10-K, accession 0001018724-26-000004); nine months to Sept. 30, 2026 584,069; nine months to Sept. 30, 2025 503,538 (Q3 2026 10-Q, accession 0001018724-26-000040). TTM = 716,924 + 584,069 − 503,538 = 797,455 $mm.';
  const G = {};
  const g = (k, o) => { G[k] = o; };

  // ---------- market data ----------
  g('price', { t: 'Current share price', what: 'The price of one common share on the observation date, in the currency it trades in.', why: 'It sets market capitalisation, enterprise value and P/E for every company, and the upside against the implied value for the target. All companies should be priced on the same date.',
    find: 'A quote provider (Financial Modeling Prep, Yahoo Finance, Bloomberg). Use the closing price on one valuation date for every company. SEC filings do not contain current prices.', calc: 'Not calculated. Record the date and whether it is a close or an intraday price.',
    ex: 'If the close is $220.00 on 31 Oct 2026 and the target trades in USD, enter 220.00 and the date 2026-10-31. ' + ILL, interp: 'A price is an observation, not a value. Comparing prices from different days mixes market moves into the multiples.',
    choose: 'Use the same closing date for the target and all peers. For a listing on another exchange, use the line whose currency you record.', mistakes: ['Mixing one company\'s intraday price with others\' closes.', 'Using an ADR price with share counts of the underlying ordinary shares (ADR ratio ignored).', 'Leaving the price date blank.'], src: ['yahoo', 'fmp'] });
  g('shares', { t: 'Actual common shares outstanding', what: 'The number of common shares in issue on a specific date, from the cover page of the newest 10-Q or 10-K.', why: 'Market cap = price × shares. Weighted-average shares are averages over a past period used for EPS and are not a count on any date.',
    find: 'Cover page of the newest 10-Q or 10-K: "As of [date], there were N shares of common stock outstanding." In SEC data: dei:EntityCommonStockSharesOutstanding. Several classes (Class A, B) are listed separately.', calc: 'Not calculated. Convert to millions (raw shares ÷ 1,000,000).',
    ex: 'Amazon\'s Q3 2026 10-Q cover page lists 10,813,138,306 shares as of October 21, 2026, which is 10,813.138 million (from the filing).', interp: 'Share counts change with buybacks and issuance. A count more than one quarter older than the price date is stale.',
    choose: 'Always the latest cover-page count. With several share classes of equal economic rights, add them; if their prices differ, value each class at its own price.', mistakes: ['Using weighted-average basic or diluted shares from the income statement.', 'Using an old 10-K count after a large buyback.', 'Mixing thousands and millions.'], src: ['edgarFts', 'secApi'] });
  g('dilutive', { t: 'Net dilutive shares', what: 'Extra shares that options, RSUs, warrants and convertibles would add, net of the treasury stock method.', why: 'On a diluted share basis, market cap and per-share value use basic + net dilutive shares. The basis must be the same for peers and the target.',
    find: 'The EPS note of the newest 10-Q ("dilutive effect of stock awards"), or a treasury stock method calculation from the equity compensation note. SEC data: IncrementalCommonSharesAttributableToShareBasedPaymentArrangements.', calc: 'Treasury stock method for options: shares × (price − strike) ÷ price for in-the-money options; RSUs count in full (net of any tax withholding you can support).',
    ex: 'Amazon\'s Q3 2026 10-Q EPS note shows a dilutive effect of stock awards of 132 million shares (from the filing). The DCF\'s share dilution guide shows the full calculation.', interp: 'Large net dilution means basic-share multiples flatter the company.', choose: 'Use the diluted basis when dilution is material (over about 1–2% of shares) for any peer, and apply it to all companies.', mistakes: ['Using diluted weighted-average shares as the current diluted count.', 'Adding gross option counts without the treasury stock method.'], src: ['edgarFts', 'cfaMult'] });
  g('mcap', { t: 'Market capitalisation', what: 'The market value of common equity: share price × actual shares outstanding.', why: 'It is the starting line of enterprise value and the numerator of P/E (in total), P/B and P/FCF.',
    find: 'Calculated here from the price and the cover-page share count. Provider market caps are a reference only: their share count and date may differ.', calc: 'Market cap = price × actual common shares outstanding (in millions, so the result is in $ millions).',
    ex: 'At an illustrative $220.00 price, Amazon\'s 10,813.138 million cover-page shares give 220.00 × 10,813.138 = 2,378,890 $mm. The share count is from the Q3 2026 10-Q; the price is illustrative.', interp: 'Compare it with the provider\'s figure: a large gap usually means a different share count or a different date.', choose: 'Basic shares by default; switch the whole model to the diluted basis when dilution is material.', mistakes: ['Multiplying by weighted-average shares.', 'Multiplying a USD price by shares of a foreign ordinary listing without the ADR ratio.'], src: ['cfaMult'] });
  g('fx', { t: 'Exchange rate', what: 'Units of the share-price currency per one unit of the currency the financial statements are reported in.', why: 'Enterprise value is in the price currency, while revenue and EBITDA are in the reporting currency. Without a rate the multiple divides one currency by another.',
    find: 'Federal Reserve H.10 release (weekly), a central bank reference rate, or your data terminal, on the price date. Record the date and the source.', calc: 'Converted metric = metric in reporting currency × rate. The multiple itself is currency-neutral only when both sides are in the same currency.',
    ex: 'A company reports in TWD and its ADR trades in USD. With an illustrative rate of 0.0310 USD per TWD, TTM EBITDA of 2,000,000 TWD mm becomes 62,000 USD mm. ' + ILL, interp: 'A wrong rate scales every multiple for that company by the same error.', choose: 'Use the spot rate on the price date for balance-sheet items and EV. For TTM flows, an average rate is also defensible; state which you used.', mistakes: ['Entering the inverse rate (TWD per USD).', 'Leaving the rate blank and comparing raw numbers across currencies.'], src: ['fedH10'] });

  // ---------- EV build ----------
  const debtLine = (t, what, find, extra) => g(t[0], Object.assign({ t: t[1], what, why: 'Enterprise value adds every claim senior to common equity, so that EV matches the operating metric, which is earned for all capital providers.', find, calc: 'Use the carrying value on the newest balance sheet unless market value differs materially (for example distressed bonds).', interp: 'A larger claim raises EV and lowers the equity value a given EV implies.', choose: 'Include it for the target and every peer in the same way.', mistakes: ['Counting the current portion twice (in short-term debt and in total long-term debt).', 'Using a stale 10-K figure when a newer 10-Q exists.'], src: ['edgarFts', 'cfaMult'] }, extra));
  debtLine(['stBorrow', 'Short-term borrowings'], 'Commercial paper, bank lines drawn and other borrowings due within a year, excluding the current portion of long-term debt.', 'Balance sheet, current liabilities: "Short-term borrowings" or "Commercial paper". SEC tags ShortTermBorrowings, CommercialPaper.', { ex: 'Short-term borrowings 1,200 + current portion 800 + long-term debt 9,000 = 11,000 $mm of debt. ' + ILL });
  debtLine(['ltdCurrent', 'Current portion of long-term debt'], 'The part of long-term debt due within twelve months.', 'Balance sheet, current liabilities, or the debt note table ("less current portion"). SEC tag LongTermDebtCurrent. When the company only tags total long-term debt (LongTermDebt) the current portion is already inside it and this line is 0.', { ex: 'Debt note: total long-term debt 9,800, of which current 800, non-current 9,000. Enter 800 here and 9,000 below, never 9,800 below as well. ' + ILL });
  debtLine(['ltdNoncurrent', 'Long-term debt, non-current'], 'Bonds, notes and term loans due after twelve months, at carrying value.', 'Balance sheet, non-current liabilities, and the debt note (face value, unamortised discount, fair value). SEC tags LongTermDebtNoncurrent or LongTermDebt.', { ex: 'Face value 9,100 less unamortised discount 100 = carrying value 9,000 $mm. The debt note\'s fair value (say 8,600) is the market value of debt. ' + ILL });
  debtLine(['finLease', 'Finance lease liabilities'], 'Lease obligations classified as finance leases (US GAAP ASC 842). Their cost appears as depreciation and interest, below EBITDA.', 'Lease note: "finance lease liabilities", current and non-current. SEC tags FinanceLeaseLiability (or the current and non-current parts).', { why: 'Because their cost is already outside EBITDA, finance leases are debt and belong in EV under any lease policy.', ex: 'Amazon reported finance lease liabilities of 14,495 $mm at Sept. 30, 2026 (Q3 2026 10-Q; from the filing).' });
  g('opLease', { t: 'Operating lease liabilities', what: 'The present value of remaining operating lease payments (US GAAP ASC 842).', why: 'Under US GAAP the operating lease cost is an operating expense inside EBITDA. Adding the liability to EV while EBITDA still bears the rent counts the leases twice. Under IFRS 16 all lease costs leave EBITDA, so IFRS EBITDA pairs with an EV that includes lease liabilities.',
    find: 'Lease note: "operating lease liabilities", current and non-current. SEC tags OperatingLeaseLiability or its current and non-current parts.', calc: 'Exclude (default): leave the liability out and keep US GAAP EBITDA. Include: add the liability to EV and use EBITDA before rent (EBITDAR) or IFRS-style EBITDA for every company.',
    ex: 'A retailer has EBITDA of 5,000 including 600 of operating lease cost, and lease liabilities of 4,500. Consistent pairs: EV excluding leases ÷ 5,000, or EV including 4,500 ÷ 5,600. Mixing them (EV including 4,500 ÷ 5,000) overstates the multiple. ' + ILL,
    interp: 'Lease-heavy peers (retail, airlines, restaurants) look cheaper or dearer only because of this choice if it is applied inconsistently.', choose: 'With all peers on US GAAP, exclude (the default). With IFRS peers in the set, either include leases and add back lease cost for the US GAAP companies, or exclude leases and deduct lease depreciation and interest from the IFRS companies\' EBITDA.', mistakes: ['Adding operating leases to EV and dividing by US GAAP EBITDA.', 'Comparing IFRS and US GAAP EBITDA multiples without an adjustment.'], src: ['ifrs16', 'cfaMult', 'damEbitda'] });
  g('preferred', { t: 'Preferred equity', what: 'Preferred shares ranking ahead of common equity.', why: 'Preferred holders have a claim on the firm\'s value that common shareholders do not get, so it is added to EV.', find: 'Balance sheet (equity section or mezzanine) and the equity note. SEC tag PreferredStockValue (carrying value). Use liquidation or market value when it differs materially.', calc: 'Carrying, liquidation or market value: one basis for all companies.', ex: 'Liquidation preference 25 × 40 million shares = 1,000 $mm. ' + ILL, interp: 'Convertible preferred that is likely to convert belongs in diluted shares instead (do not count it twice).', choose: 'Most companies have none: leave the line empty (not reported).', mistakes: ['Counting convertible preferred both as a claim and in diluted shares.'], src: ['cfaMult', 'edgarFts'] });
  g('nci', { t: 'Noncontrolling interests', what: 'The share of consolidated subsidiaries owned by outside shareholders.', why: 'Consolidated EBITDA includes 100% of those subsidiaries, so EV must include the outside owners\' claim to match it.', find: 'Balance sheet equity section: "noncontrolling interests". SEC tag MinorityInterest. Market value is better when the subsidiary is listed.', calc: 'Book value by default; market value of the outside stake when available.', ex: 'A parent owns 80% of a listed subsidiary worth 5,000: noncontrolling interest at market = 20% × 5,000 = 1,000 $mm. ' + ILL, interp: 'Large noncontrolling interests at book value can understate EV.', choose: 'Book value unless a listed price is available.', mistakes: ['Leaving it out while using consolidated EBITDA.'], src: ['cfaMult', 'damCh17'] });
  g('otherClaims', { t: 'Other debt-like claims', what: 'Obligations that behave like debt but are not borrowings: unfunded pensions (after tax), deferred consideration, litigation settlements payable, and similar.', why: 'Leaving a large debt-like claim out of EV makes the company look cheap on EV multiples.', find: 'Notes on pensions (funded status), commitments and contingencies, and acquisitions.', calc: 'Enter the after-tax amount where the payment is tax-deductible. Include an item only if its cost is not already in EBITDA.', ex: 'Unfunded pension of 1,000 at a 21% tax rate = 790 $mm after tax. ' + ILL, interp: 'Apply the same items to every peer or the multiples are not comparable.', choose: 'Include only material items you can identify for all companies.', mistakes: ['Adding a pension deficit while EBITDA already bears the pension service cost and interest.', 'Including it for the target only.'], src: ['cfaMult', 'damCh17'] });
  g('cash', { t: 'Cash and cash equivalents', what: 'Cash and investments that mature within three months of purchase.', why: 'Cash is not needed to earn EBITDA, so EV subtracts it. It is required: enter 0 only if the company truly has none.', find: 'Balance sheet, first line of current assets. SEC tag CashAndCashEquivalentsAtCarryingValue.', calc: 'Use the newest balance sheet. Restricted cash is excluded unless it is freely available.', ex: 'Cash 5,000 + short-term investments 2,000 = 7,000 $mm subtracted from EV. ' + ILL, interp: 'Very large cash balances reduce EV and raise EV multiples\' sensitivity to small EBITDA changes.', choose: 'Subtract all of it unless a portion is trapped or needed for operations and you can show why.', mistakes: ['Subtracting restricted cash.', 'Using the 10-K figure when the 10-Q is newer.'], src: ['edgarFts', 'cfaMult'] });
  g('sti', { t: 'Short-term investments', what: 'Marketable securities and time deposits held as liquidity.', why: 'Like cash, they do not produce operating income, so EV subtracts them.', find: 'Balance sheet current assets: "marketable securities" or "short-term investments". SEC tags MarketableSecuritiesCurrent, ShortTermInvestments.', calc: 'Carrying (fair) value on the newest balance sheet.', ex: 'See the cash example. ' + ILL, interp: 'Excluding it (by unticking) is unusual and must be explained.', choose: 'Subtract it for every company.', mistakes: ['Also subtracting long-term strategic investments here.'], src: ['edgarFts'] });
  g('otherNonop', { t: 'Other non-operating assets', what: 'Assets whose income is not in EBITDA: equity-method stakes, long-term investments, crypto holdings, assets held for sale.', why: 'If EBITDA excludes their income, EV should exclude their value too. Equity-method income is usually below EBITDA.', find: 'Balance sheet and the investments note. SEC tags EquityMethodInvestments, CryptoAssetFairValue. They are offered as references and never added automatically.', calc: 'Fair value where reported; otherwise carrying value. Tick the line to subtract it.', ex: 'Strategy (MSTR) reported crypto assets of 49,672 $mm at June 30, 2026 (Q2 2026 10-Q; from the filing). Leaving them in EV values the bitcoin as if it produced EBITDA.', interp: 'Large non-operating assets make EV multiples misleading unless removed.', choose: 'Subtract only assets whose income is not in the metric you divide by, and do the same for peers.', mistakes: ['Subtracting an investment whose income is included in EBITDA (double counting).'], src: ['cfaMult', 'damCh17'] });
  g('ev', { t: 'Enterprise value', what: 'The market value of the whole business available to all capital providers.', why: 'It is the numerator of EV/Revenue, EV/EBITDA and EV/EBIT, which compare companies regardless of how they are financed.',
    find: 'Built line by line on this page from the market cap and the balance sheet. Provider EV figures are a reference only.', calc: 'EV = market cap + debt (borrowings, current and non-current long-term debt, finance leases) + operating leases (if the lease policy includes them) + preferred + noncontrolling interests + other claims − cash − short-term investments − other non-operating assets (if ticked).',
    ex: 'Market cap 50,000 + debt 11,000 + noncontrolling interests 500 − cash 5,000 − short-term investments 2,000 = 54,500 $mm. ' + ILL, interp: 'A negative EV (cash above market cap plus debt) makes EV multiples meaningless (N/M).', choose: 'Same definition and the same lease policy for the target and every peer.', mistakes: ['Adding operating leases for some companies only.', 'Using a balance sheet from a different date than the TTM period.', 'Forgetting noncontrolling interests with consolidated EBITDA.'], src: ['cfaMult', 'damCh17', 'damEbitda'] });

  // ---------- operating metrics ----------
  const per = 'Use TTM for trailing multiples, the last fiscal year for FY multiples, and date-aligned consensus for NTM or FY+1.';
  g('rev', { t: 'Revenue', what: 'Total net sales for the period.', why: 'The denominator of EV/Revenue and the base for every margin.', find: 'Income statement first line. SEC tags RevenueFromContractWithCustomerExcludingAssessedTax or Revenues. ' + per, calc: 'TTM = latest fiscal year + current year-to-date − prior-year comparable year-to-date.', ex: AMZN_TTM, interp: 'Revenue is rarely negative and less affected by accounting choices than earnings, but it ignores profitability.', choose: per, mistakes: ['Mixing gross and net revenue recognition (agents vs principals).', 'Adding four quarters from different fiscal years.'], src: ['edgarFts', 'secApi'] });
  g('gp', { t: 'Gross profit', what: 'Revenue minus cost of revenue.', why: 'Shows the margin structure; companies with very different gross margins are often not comparable.', find: 'Income statement; some companies do not report it (calculated as revenue − cost of revenue where possible).', calc: 'Gross profit = revenue − cost of revenue.', ex: 'Revenue 10,000 − cost of revenue 6,000 = 4,000; gross margin 40%. ' + ILL, interp: 'Gross margin differences signal different business models.', choose: 'Use it for comparability screening, not as a multiple denominator.', mistakes: ['Comparing gross margins where some companies put depreciation in cost of revenue and others do not.'], src: ['edgarFts'] });
  g('ebitda', { t: 'EBITDA', what: 'Earnings before interest, taxes, depreciation and amortisation. Here: operating income (EBIT) + depreciation and amortisation from the cash flow statement.', why: 'The most used denominator for operating companies: it is before financing choices and before non-cash D&A.',
    find: 'Not a GAAP line. Operating income from the income statement plus D&A from the cash flow statement. Company "adjusted EBITDA" is a non-GAAP measure with its own definition; record it only as an adjustment you can justify.', calc: 'EBITDA = EBIT + D&A. TTM: TTM EBIT + TTM D&A, both ending on the same date.',
    ex: 'EBIT 5,000 + D&A 2,000 = EBITDA 7,000 $mm. ' + ILL, interp: 'EBITDA ignores capital intensity: two companies with the same EBITDA but different capex needs are worth different amounts.', choose: 'Use one definition for all companies. Stock-based compensation stays as an expense (it is not added back) unless you add it back for every company.', mistakes: ['Mixing company-reported adjusted EBITDA with calculated EBITDA.', 'Adding back stock-based compensation for some peers only.', 'Comparing IFRS 16 EBITDA (before all lease costs) with US GAAP EBITDA.'], src: ['secNonGaap', 'damEbitda', 'cfaMult'] });
  g('ebit', { t: 'EBIT (operating income)', what: 'Operating income after depreciation and amortisation, before interest and tax.', why: 'Includes the cost of using up assets, so it suits capital-intensive businesses better than EBITDA.', find: 'Income statement: "operating income". SEC tag OperatingIncomeLoss.', calc: 'Reported. TTM by the FY + YTD − prior YTD rule.', ex: 'Revenue 10,000 − operating expenses 8,500 = EBIT 1,500; margin 15%. ' + ILL, interp: 'Amortisation of acquired intangibles lowers EBIT for acquisitive companies: consider an adjustment for consistency.', choose: per, mistakes: ['Using pretax income (after interest) instead of operating income.'], src: ['edgarFts', 'damEbitda'] });
  g('ni', { t: 'Net income attributable to common shareholders', what: 'Profit after interest, tax and noncontrolling interests, less preferred dividends.', why: 'The equity earnings behind P/E.', find: 'Income statement: "net income attributable to [company]". SEC tags NetIncomeLoss or NetIncomeLossAvailableToCommonStockholdersBasic.', calc: 'Reported; TTM by the FY + YTD − prior YTD rule.', ex: 'Net income 2,000 − preferred dividends 50 = 1,950 to common. ' + ILL, interp: 'Affected by leverage, tax and one-off items.', choose: 'Use for P/E only together with diluted EPS on the same basis.', mistakes: ['Using net income including noncontrolling interests (ProfitLoss).'], src: ['edgarFts', 'damPE'] });
  g('eps', { t: 'Diluted EPS', what: 'Net income to common ÷ diluted weighted-average shares, as reported.', why: 'The denominator of P/E.', find: 'Income statement bottom: "diluted earnings per share". SEC tag EarningsPerShareDiluted. For TTM: FY + YTD − prior YTD of reported EPS.', calc: 'TTM EPS = FY EPS + YTD EPS − prior-year YTD EPS. EPS is not strictly additive because share counts change; the difference is usually small.', ex: 'FY EPS 4.00 + nine-month EPS 3.40 − prior nine-month EPS 2.90 = TTM EPS 4.50. ' + ILL, interp: 'Negative EPS makes P/E N/M.', choose: 'Diluted EPS for all companies. Basic EPS only if diluted is not reported.', mistakes: ['Mixing basic and diluted EPS across peers.', 'Using adjusted EPS for some peers and GAAP EPS for others.'], src: ['edgarFts', 'damPE'] });
  g('capex', { t: 'Capital expenditures', what: 'Cash spent on property, plant and equipment.', why: 'Shows capital intensity: EBITDA multiples of capital-heavy companies need to be read with capex.', find: 'Cash flow statement, investing activities. SEC tags PaymentsToAcquirePropertyPlantAndEquipment or PaymentsToAcquireProductiveAssets (some report it net of proceeds).', calc: 'Reported, as a positive outflow. TTM by the FY + YTD − prior YTD rule.', ex: 'Capex 1,500 on revenue 10,000 = 15% capital intensity. ' + ILL, interp: 'Capex/revenue differences of more than a few points weaken EBITDA comparability.', choose: 'Use for screening and for the comparability criteria.', mistakes: ['Ignoring assets acquired under finance leases (not in capex).'], src: ['edgarFts'] });
  g('fcf', { t: 'Free cash flow (CFO − CapEx)', what: 'Operating cash flow minus capital expenditures.', why: 'Cash available after reinvestment. Because it is after interest, it pairs with equity value (P/FCF), not EV.', find: 'Cash flow statement: operating cash flow and capital expenditures.', calc: 'FCF = cash from operations − capital expenditures. Not unlevered FCF to the firm (which would add back after-tax interest).', ex: 'CFO 3,000 − capex 1,200 = FCF 1,800 $mm. ' + ILL, interp: 'Volatile with working capital swings; check several years.', choose: 'P/FCF suits mature, stable cash generators.', mistakes: ['Dividing EV by levered FCF (inconsistent numerator and denominator).'], src: ['cfaMult', 'damCh18'] });
  g('equity', { t: 'Book equity', what: 'Total stockholders\' equity attributable to the parent.', why: 'The denominator of P/Book, relevant for banks, insurers and asset-heavy companies.', find: 'Balance sheet: "total stockholders\' equity". SEC tag StockholdersEquity.', calc: 'Reported, newest balance sheet.', ex: 'Market cap 12,000 ÷ book equity 8,000 = P/B 1.50×. ' + ILL, interp: 'Negative book equity (after buybacks) makes P/B N/M.', choose: 'Use P/B mainly for financial companies.', mistakes: ['Using equity including noncontrolling interests.'], src: ['damPBV', 'cfaMult'] });
  g('ttm', { t: 'Trailing twelve months (TTM)', what: 'The latest twelve months of results, built from the last annual report and the newest quarterly report.', why: 'More current than the last fiscal year, and the standard for trailing multiples.', find: 'The last 10-K (fiscal year) and the newest 10-Q (year-to-date and prior-year year-to-date columns).', calc: 'TTM = latest fiscal year + current year-to-date − prior-year comparable year-to-date.', ex: AMZN_TTM, interp: 'All companies\' TTM periods should end within about one quarter of each other.', choose: 'Use TTM for trailing multiples. If no 10-Q follows the fiscal year, TTM equals the fiscal year.', mistakes: ['Adding the fiscal year to the full year-to-date without subtracting the prior year-to-date (double counting).', 'Mixing TTM periods ending in different years.'], src: ['secApi', 'edgarFts'] });
  g('ntm', { t: 'Next twelve months (NTM) and FY+1', what: 'NTM is the twelve months after the valuation date. FY+1 is the next full fiscal year. They are different periods unless the fiscal year has just begun.', why: 'Forward multiples price expected earnings. Mixing NTM for some peers and FY+1 for others compares different horizons.',
    find: 'Consensus analyst estimates (here: Financial Modeling Prep consensus mean, with the analyst count and the fiscal year-end of each estimate). Reported filings contain no forecasts.', calc: 'NTM = w × FY+1 + (1 − w) × FY+2, where w = days from the valuation date to the FY+1 year-end ÷ days in that fiscal year.',
    ex: 'Valuation date 31 Oct 2026, fiscal year ending 31 Dec 2026: w = 61 ÷ 365 = 16.7%. With FY+1 EBITDA 100 and FY+2 120, NTM = 0.167 × 100 + 0.833 × 120 = 116.7. ' + ILL, interp: 'Forward multiples are lower than trailing ones for growing companies.', choose: 'NTM for peers with different fiscal year-ends; FY+1 only when year-ends align (the comps table warns when they differ by more than a month).', mistakes: ['Calling FY+1 "NTM".', 'Using estimates of different dates or from different providers for different peers.'], src: ['fmp', 'cfaMult'] });
  g('growth', { t: 'Revenue growth', what: 'TTM revenue ÷ TTM revenue one year earlier − 1 (or fiscal-year growth when TTM is not available).', why: 'Faster-growing companies usually trade at higher multiples; growth is the main reason for a premium or discount.', find: 'Calculated from the imported revenue figures.', calc: 'Growth = revenue (this period) ÷ revenue (same period a year earlier) − 1.', ex: 'TTM revenue 1,130 ÷ TTM revenue a year earlier 1,000 − 1 = 13.0%. ' + ILL, interp: 'Compare it with the peer median on the summary scatter chart.', choose: 'Use organic growth (excluding acquisitions) when acquisitions are material; note the adjustment.', mistakes: ['Comparing reported growth inflated by an acquisition with organic growth.'], src: ['damCh17'] });
  g('margins', { t: 'Margins', what: 'Gross, EBITDA, EBIT and net margins: each metric ÷ revenue.', why: 'Margin differences explain much of the dispersion in EV/Revenue multiples.', find: 'Calculated from the imported figures.', calc: 'Margin = metric ÷ revenue for the same period.', ex: 'EBITDA 7,000 ÷ revenue 40,000 = 17.5%. ' + ILL, interp: 'A company with half the peer margin deserves roughly half the EV/Revenue multiple, all else equal.', choose: 'Use normalised margins when one-off items are material.', mistakes: ['Mixing periods (TTM EBITDA over FY revenue).'], src: ['damPS', 'damCh20'] });

  // ---------- multiples ----------
  const mult = (k, o) => g(k, Object.assign({ src: ['cfaMult', 'damCh17'] }, o));
  mult('m_ev_rev', { t: 'EV / Revenue', what: 'Enterprise value ÷ revenue.', why: 'Works when earnings are low or negative (early-stage or cyclical lows), because revenue is almost always positive.', find: 'EV from the EV build; revenue for the selected period.', calc: 'EV / Revenue = enterprise value ÷ revenue.', ex: 'EV 54,500 ÷ TTM revenue 40,000 = 1.36×. ' + ILL, interp: 'It ignores profitability: a low-margin company looks cheap on it. Read it together with EBITDA margins.', choose: 'Use when EBITDA is negative or not meaningful, and only with peers of similar margins.', mistakes: ['Applying a high-margin peer group\'s EV/Revenue to a low-margin target.', 'Dividing market cap (not EV) by revenue.'], src: ['damPS', 'damCh20', 'cfaMult'] });
  mult('m_ev_ebitda', { t: 'EV / EBITDA', what: 'Enterprise value ÷ EBITDA.', why: 'The default operating multiple: independent of leverage and of depreciation policy.', find: 'EV from the EV build; EBITDA = EBIT + D&A for the selected period.', calc: 'EV / EBITDA = enterprise value ÷ EBITDA.', ex: 'EV 54,500 ÷ TTM EBITDA 7,000 = 7.79×. ' + ILL, interp: 'Capital-intensive companies deserve lower EV/EBITDA for the same growth. Lease treatment, adjusted EBITDA definitions and stock-based compensation all change it.', choose: 'Default for profitable operating companies with comparable capital intensity.', mistakes: ['N/M cases treated as zero.', 'Mixing adjusted and reported EBITDA.', 'Inconsistent lease treatment.'], src: ['damEbitda', 'cfaMult', 'secNonGaap'] });
  mult('m_ev_ebit', { t: 'EV / EBIT', what: 'Enterprise value ÷ operating income.', why: 'Includes depreciation and amortisation, so it reflects capital intensity.', find: 'EV from the EV build; EBIT for the selected period.', calc: 'EV / EBIT = enterprise value ÷ EBIT.', ex: 'EV 54,500 ÷ TTM EBIT 5,000 = 10.9×. ' + ILL, interp: 'Acquisitive peers with large amortisation look expensive on EV/EBIT.', choose: 'Use for capital-intensive industries, or alongside EV/EBITDA.', mistakes: ['Using pretax income.'], src: ['damEbitda', 'cfaMult'] });
  mult('m_pe', { t: 'P / E', what: 'Share price ÷ diluted EPS (equivalently equity market value ÷ net income to common, when share bases match).', why: 'The most quoted equity multiple; suits stable, profitable companies with similar leverage.', find: 'Price; diluted EPS for the selected period.', calc: 'P/E = share price ÷ diluted EPS.', ex: 'Price 60.00 ÷ TTM diluted EPS 4.50 = 13.3×. ' + ILL, interp: 'It is an equity multiple: apply it to the target\'s EPS to get a value per share directly. Never apply it to EV or run an enterprise-to-equity bridge on it. Leverage and tax differences distort it.', choose: 'Use for mature profitable companies, banks and insurers. Not for loss-makers (N/M).', mistakes: ['Applying P/E to EBITDA or to EV.', 'Mixing basic and diluted EPS.', 'Averaging P/E including very high values from near-zero earnings.'], src: ['damPE', 'damCh18', 'cfaMult'] });
  mult('m_pb', { t: 'P / Book', what: 'Market capitalisation ÷ book equity.', why: 'Relevant where book value is close to economic value: banks, insurers, asset holders.', find: 'Market cap; book equity from the balance sheet.', calc: 'P/B = market capitalisation ÷ stockholders\' equity.', ex: 'Market cap 12,000 ÷ book equity 8,000 = 1.50×. ' + ILL, interp: 'Driven by return on equity: higher ROE, higher P/B.', choose: 'Financial companies; rarely informative for asset-light businesses.', mistakes: ['Using it for software or services companies with little book equity.'], src: ['damPBV', 'cfaMult'] });
  mult('m_p_fcf', { t: 'Price / FCF', what: 'Market capitalisation ÷ free cash flow (CFO − capex).', why: 'Cash-based equity multiple. EV/FCFF would need unlevered free cash flow, which is not consistently defined from reported data, so the levered version pairs with equity value.', find: 'Market cap; CFO and capex from the cash flow statement.', calc: 'P/FCF = market cap ÷ (CFO − capex).', ex: 'Market cap 12,000 ÷ FCF 800 = 15.0×. ' + ILL, interp: 'Working-capital swings make single-year FCF noisy.', choose: 'Mature cash generators with stable working capital.', mistakes: ['Dividing EV by levered FCF.'], src: ['cfaMult', 'damCh18'] });
  g('nm', { t: 'N/M and N/A', what: 'N/M (not meaningful): the denominator or EV is zero or negative, so the ratio has no economic meaning. N/A (not available): an input is missing.', why: 'A multiple of a negative number is negative and would distort the statistics; it is left out of them, and the table says why.', find: 'Shown automatically in the comps table with the reason.', calc: 'Multiple = N/M if denominator ≤ 0 or EV ≤ 0; N/A if any input is missing.', ex: 'EV 5,000 ÷ EBITDA −200 = N/M, not −25×. ' + ILL, interp: 'Many N/M peers for one multiple mean that multiple is the wrong tool for this group.', choose: 'Switch to a multiple with a positive denominator for most peers (often EV/Revenue).', mistakes: ['Replacing N/M with zero.', 'Keeping negative multiples in the median.'], src: ['damCh17'] });

  // ---------- statistics ----------
  g('stats', { t: 'Peer statistics', what: 'Minimum, 25th percentile, mean, median, 75th percentile, maximum and count of the valid observations of included peers.', why: 'The benchmark multiple comes from these statistics. The median resists outliers better than the mean.', find: 'Calculated from the comps table; excluded peers, N/M and N/A observations and observations you excluded are not counted. The target is never included.', calc: 'Quartiles use the PERCENTILE.INC convention (Excel QUARTILE.INC): position = (n − 1) × p in the sorted list, interpolated linearly.', ex: 'Sorted multiples 7, 8, 9, 10, 12: median = 9; 25th percentile: position 1 → 8; 75th: position 3 → 10; mean = 9.2. ' + ILL, interp: 'A wide interquartile range means the peer group prices the business inconsistently: be careful with the point estimate.', choose: 'Median by default.', mistakes: ['Including the target in its own benchmark.', 'Using the mean with an extreme outlier.'], src: ['msPct', 'damCh17'] });
  g('outlier', { t: 'Outliers', what: 'Observations below Q1 − 1.5 × IQR or above Q3 + 1.5 × IQR (Tukey fences), with at least four valid observations.', why: 'Extreme values (often from near-zero denominators) distort the mean. They are flagged, never removed automatically.', find: 'Flagged in the comps table.', calc: 'IQR = Q3 − Q1; fences = Q1 − 1.5 × IQR and Q3 + 1.5 × IQR.', ex: 'Q1 7, Q3 10, IQR 3: fences 2.5 and 14.5; an observation of 30× is flagged. ' + ILL, interp: 'A flag is a prompt to investigate (a one-off charge, a near-zero EBITDA), not proof the observation is wrong.', choose: 'Exclude an observation only with a written reason; it stays visible in the table.', mistakes: ['Deleting peers that make the answer inconvenient.'], src: ['msPct', 'damCh17'] });

  // ---------- peers ----------
  g('peerSel', { t: 'Peer selection', what: 'The set of listed companies whose pricing is used to value the target.', why: 'The valuation is only as good as the comparability of the peers. Industry codes alone are not enough.', find: 'Competitors named in the target\'s 10-K (Item 1, "Competition"), peers named by the peers themselves, provider suggestions, and industry classifications.', calc: 'Not a calculation: judge business model, products, customers, revenue mix, geography, size, growth, profitability, capital intensity and risk.',
    ex: 'Amazon combines retail, cloud infrastructure (AWS) and advertising. A retail peer set (Walmart, Costco) ignores AWS; a cloud set ignores retail margins. A sum-of-the-parts valuation (below) handles this better than one consolidated peer group.', interp: 'Core peers are the closest; Broader peers widen the set when Core is small.', choose: 'Aim for 5–10 Core peers with a written reason each. Mark doubtful ones Broader rather than mixing them in.', mistakes: ['Choosing peers only by SIC or GICS code.', 'Choosing peers to reach a target answer.', 'Including the target itself.'], src: ['damCh17', 'cfaMult', 'edgarFts'] });
  g('relevance', { t: 'Comparability criteria', what: 'Five transparent tests against the target: same industry classification, revenue within 0.25× to 4×, growth within ±10 points, EBITDA margin within ±10 points, capex/revenue within ±5 points.', why: 'A quick, explainable screen. It counts how many tests a peer passes; it is never proof of comparability.', find: 'Calculated from the imported data; a test without data shows as not tested.', calc: 'Count of tests met ÷ tests with data.', ex: '3 of 5 met: the peer is similar in size, growth and margin but in a different industry code and with higher capex.', interp: 'A low count is a reason to look closer, or to mark the peer Broader.', choose: 'Use the criteria as a prompt; your reasons decide.', mistakes: ['Treating the count as a statistical similarity score.'], src: ['damCh17'] });
  g('sotp', { t: 'Sum-of-the-parts', what: 'Valuing each business segment with its own peer group and multiple, then adding the parts and the bridge.', why: 'A conglomerate\'s consolidated multiple mixes businesses that trade at very different multiples.', find: 'Segment note in the 10-K ("segment information"): revenue and operating income by segment.', calc: 'Value = Σ (segment metric × segment peer multiple) − net claims; per share ÷ shares.', ex: 'Segment A EBIT 10,000 × 20× + segment B EBIT 5,000 × 8× = 240,000 EV. ' + ILL, interp: 'If the parts add to much more than the consolidated comps value, the consolidated peer group is probably mismatched.', choose: 'Use when segments differ materially in growth, margin or risk. Build one comps model per segment here and add the results.', mistakes: ['Applying segment multiples to segment EBITDA that excludes corporate costs, then forgetting those costs.'], src: ['damCh20', 'edgarFts'] });

  // ---------- adjustments ----------
  g('normalize', { t: 'Financial adjustments (normalisation)', what: 'Changes to reported metrics that remove items which distort comparison: restructuring, litigation, impairments, gains on asset sales, acquisition costs, accounting policy and lease differences, fiscal calendar changes, discontinued operations, currency effects.', why: 'Multiples compare recurring earning power. A one-off charge in one peer\'s TTM EBITDA distorts its multiple.',
    find: 'The income statement, the MD&A, the segment note and the company\'s non-GAAP reconciliation (which is a starting point, not an authority).', calc: 'Normalised metric = reported metric ± analyst adjustments. Enter amounts that are added to the reported figure (a charge added back is positive).',
    ex: 'Reported TTM EBITDA 6,400 + restructuring charge 300 + litigation settlement 150 − gain on sale 200 = normalised 6,650 $mm. ' + ILL, interp: 'Compare reported and normalised multiples: a large gap means the conclusion depends on your adjustments.', choose: 'Adjust only items that are genuinely non-recurring and that you would adjust for every company. Record a reason and a source for each material item.', mistakes: ['Treating recurring costs as one-off because the company labels them "adjusted".', 'Adjusting the target but not the peers.', 'Adding back stock-based compensation for some companies only.'], src: ['secNonGaap', 'cfaMult', 'edgarFts'] });

  // ---------- valuation ----------
  g('benchmark', { t: 'Benchmark statistic', what: 'Which peer statistic becomes the selected multiple: median (default), mean, 25th or 75th percentile, a custom peer weighting, or a manual multiple.', why: 'The median is robust to outliers, but it is not "fair value": the target may deserve to trade above or below it.', find: 'The comps table statistics.', calc: 'Selected multiple = benchmark × (1 + premium or discount).', ex: 'Peer median EV/EBITDA 9.0× with a 10% premium for faster growth = 9.9×. ' + ILL, interp: 'Choose the 75th percentile only with evidence that the target is better than most peers on the drivers of value.', choose: 'Median unless your written comparison supports another point.', mistakes: ['Picking the statistic that gives the hoped-for answer.'], src: ['damCh17', 'cfaMult'] });
  g('premium', { t: 'Premium or discount', what: 'An adjustment to the benchmark for differences in growth, profitability, business mix, competitive advantage, scale, risk, capital intensity or leverage.', why: 'Multiples reflect fundamentals; a target that differs from its peers deserves a different multiple.', find: 'Compare the target with the peer median on the summary charts and the comps table.', calc: 'Selected = benchmark × (1 + premium). A discount is a negative premium.', ex: 'Target growth 15% vs peer median 8%; the scatter of EV/EBITDA against growth suggests about +0.15× per point of growth: 7 points × 0.15 = 1.05× above a 9.0× median, a premium of about 12%. ' + ILL, interp: 'Without a reason, a premium is an opinion; the checklist asks for one.', choose: 'Tie the size to a measurable gap where possible (regression of multiple on growth or margin across peers).', mistakes: ['Round-number premiums with no analysis.', 'Adding a premium for growth that is already reflected by using a forward multiple.'], src: ['damCh17', 'damCh18'] });
  g('impliedEv', { t: 'Implied enterprise value', what: 'Selected EV multiple × the target\'s metric for the same period.', why: 'The first step of a comps valuation with an EV multiple.', find: 'Calculated.', calc: 'Implied EV = selected multiple × target metric (EBITDA, EBIT or revenue), using the same period and definition as the peer multiples.', ex: '9.9× × target TTM EBITDA 1,200 = implied EV 11,880 $mm. ' + ILL, interp: 'A negative or zero target metric gives no meaningful value (N/M).', choose: 'Normalised metric if you normalised the peers.', mistakes: ['Applying a TTM multiple to an NTM metric.'], src: ['cfaMult'] });
  g('bridge', { t: 'Enterprise-to-equity bridge', what: 'From implied EV to implied equity value: subtract debt and other claims, add cash and non-operating assets.', why: 'Common shareholders own what is left after senior claims. The same lines and choices as the target\'s own EV build are used, so nothing is counted twice.', find: 'The target\'s EV build on Target Company.', calc: 'Implied equity = implied EV − (debt + leases if included + preferred + noncontrolling interests + other claims) + (cash + short-term investments + ticked non-operating assets).', ex: 'Implied EV 11,880 − debt 3,000 − noncontrolling interests 200 + cash 1,500 = implied equity 10,180 $mm. ' + ILL, interp: 'Not used for P/E, P/B or P/FCF, which give equity value directly.', choose: 'Keep the bridge identical to the target\'s EV definition.', mistakes: ['Applying a bridge to a P/E result.', 'Including operating leases in the bridge but not in peer EVs.'], src: ['cfaMult', 'damCh17'] });
  g('perShare', { t: 'Implied value per share', what: 'Implied equity value ÷ shares, on the model\'s share basis (basic actual shares by default, or basic + net dilutive).', why: 'Comparable with the share price.', find: 'Calculated.', calc: 'Per share = implied equity ÷ shares. For P/E: selected P/E × target diluted EPS.', ex: '10,180 ÷ 250 million shares = $40.72. ' + ILL, interp: 'Uses the same share basis as the peer market caps.', choose: 'Diluted basis when dilution is material.', mistakes: ['Dividing by weighted-average shares.'], src: ['cfaMult'] });
  g('upside', { t: 'Upside or downside', what: 'How far the implied value is above or below the current price.', why: 'A summary of relative mispricing under your assumptions; not a recommendation.', find: 'Calculated.', calc: 'Upside = (implied value per share ÷ current share price − 1) × 100.', ex: '($40.72 ÷ $36.00 − 1) × 100 = +13.1%. ' + ILL, interp: 'Peer pricing can itself be too high or too low: comps measure relative value only.', choose: 'Read it next to the valuation range, not alone.', mistakes: ['Treating a comps upside as intrinsic value.'], src: ['damCh17'] });
  g('range', { t: 'Valuation range', what: 'Implied values at the peer 25th percentile, median and 75th percentile multiples, plus your own low, central and high multiples.', why: 'Shows how much the answer depends on where in the peer range the target belongs.', find: 'Calculated.', calc: 'Each row repeats the implied valuation with a different multiple.', ex: 'EV/EBITDA quartiles 7.5×, 9.0×, 10.5× applied to EBITDA 1,200 give EVs of 9,000, 10,800 and 12,600. ' + ILL, interp: 'It is a range of peer pricing, not Bear, Base and Bull business outcomes.', choose: 'Use analyst low/central/high when you have reasons to depart from the quartiles.', mistakes: ['Presenting the quartile range as a probability distribution.'], src: ['damCh17'] });
  g('sens', { t: 'Sensitivity analysis', what: 'Tables of implied value per share as the multiple and the target metric change, as forward growth changes, and as peers or peer groups change.', why: 'Shows which assumption drives the result.', find: 'Calculated with the model\'s inputs; set the ranges and increments.', calc: 'Each cell = implied valuation with that multiple and that metric (metric × (1 + change)).', ex: 'At 9.0× and EBITDA 1,200 the value is $40.72; at 10.0× and +5% EBITDA it is about $46. ' + ILL, interp: 'If removing one peer moves the value a lot, the conclusion depends on that peer.', choose: 'Ranges wide enough to cover the interquartile range of the peers.', mistakes: ['Ranges so narrow they hide the uncertainty.'], src: ['cfaMult'] });
  g('dcfComp', { t: 'DCF comparison', what: 'The DCF intrinsic value per share next to the comps implied value and the market price.', why: 'DCF estimates value from discounted projected cash flows; comps estimate relative value from how similar companies are priced. Large gaps are worth explaining, not forcing away.', find: 'A DCF model for the same company in this app.', calc: 'Difference = DCF value ÷ comps value − 1, and each against the price.', ex: 'DCF $180.00, comps $165.00, price $150.00: DCF is 9.1% above comps and both are above the price. ' + ILL, interp: 'Neither method guarantees a correct price. Check that both use the same price date and share basis.', choose: 'Compare only when the DCF is complete.', mistakes: ['Adjusting one model until it agrees with the other.'], src: ['damCh17'] });
  g('leasePolicy', Object.assign({}, G.opLease, { t: 'Lease policy (all companies)' }));
  g('shareBasis', { t: 'Share basis (all companies)', what: 'Basic: actual cover-page shares. Diluted: actual shares + net dilutive shares (treasury stock method).', why: 'Market caps, EVs and the implied per-share value must use the same basis for peers and target.', find: 'Net dilutive shares from the EPS note or a treasury stock method calculation.', calc: 'Diluted shares = basic + net dilutive.', ex: 'Basic 1,000 + net dilutive 15 = 1,015 million diluted shares. ' + ILL, interp: 'Diluted is more conservative and preferred when dilution is material.', choose: 'Diluted when any company has dilution above about 1–2%.', mistakes: ['Diluted for the target, basic for the peers.'], src: ['cfaMult'] });

  const ORDER = [['What it is', 'what'], ['Why it matters', 'why'], ['How to find the data', 'find'], ['How to calculate it', 'calc'], ['Worked example', 'ex'], ['How to interpret the result', 'interp'], ['How to choose an assumption', 'choose'], ['Common mistakes', 'mistakes'], ['Supporting sources', 'src']];
  return { S, G, ORDER };
})();
if (typeof module !== 'undefined') module.exports = CompsHelp;
